#!/bin/bash
# get_keep: print keep from config/rotate.conf (error if missing or not a positive integer).
get_keep() {
  local conf k
  conf="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/config/rotate.conf"
  k=$(sed -n 's/^keep=\([0-9][0-9]*\)$/\1/p' "$conf" | tail -1)
  [ -n "$k" ] && [ "$k" -ge 1 ] || { echo "rotate: invalid keep in $conf" >&2; return 1; }
  echo "$k"
}

