#!/bin/bash
# get_keep: print keep from config/rotate.conf (the generations to retain).
get_keep() {
  local root; root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
  local k; k=$(sed -n 's/^keep=\([0-9][0-9]*\)$/\1/p' "$root/config/rotate.conf" | tail -1)
  [ -n "$k" ] || { echo "rotate: keep is not set in config/rotate.conf" >&2; return 1; }
  echo "$k"
}

