}


# archive_prune <archive dir> <name> <keep>: keep only the newest <keep> name.<YYYYMMDD> files.
archive_prune() {
  local archive=$1 name=$2 keep=$3 f
  for f in "$archive/$name".[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]; do
    [ -e "$f" ] && echo "$f"
  done | sort -r | tail -n +$((keep + 1)) | while IFS= read -r f; do rm -f "$f"; done
}

